package main

import (
	"testing"
	"time"
)

// TestStoreExpiryBoundary covers the idle-expiry boundary with the existing
// fake-clock table helper.
func TestStoreExpiryBoundary(t *testing.T) {
	runClockTable(t, []clockCase{
		{name: "under-ttl-stays", ttl: time.Minute, advance: 30 * time.Second, wantErr: false, wantLen: 1},
		{name: "over-ttl-dropped", ttl: time.Minute, advance: 2 * time.Minute, wantErr: true, wantLen: 0},
	})
}

wrong.expiry_boundary_test.go:
package main

import (
	"testing"
	"time"
)

// TestStoreExpiryBoundary rolls its own clock plumbing instead of reusing the
// repository's table helper.
func TestStoreExpiryBoundary(t *testing.T) {
	store := NewStore(time.Minute)
	clock := time.Now()
	store.now = func() time.Time { return clock }
	store.Create("abc", "ada")
	clock = clock.Add(2 * time.Minute)
	if _, err := store.Get("abc"); err == nil {
		t.Fatal("over ttl Get: err = nil, want an error")
	}
	if got := store.Len(); got != 0 {
		t.Fatalf("Len = %d, want 0", got)
	}
}
